BEGIN TRANSACTION;
CREATE TABLE administrative_districts (
    district_id INTEGER PRIMARY KEY AUTOINCREMENT,
    district_name TEXT UNIQUE NOT NULL,
    region_name TEXT NOT NULL,
    total_links INTEGER DEFAULT 0,
    total_length_km REAL DEFAULT 0.0,
    bituminous_km REAL DEFAULT 0.0,
    gravel_km REAL DEFAULT 0.0,
    earth_km REAL DEFAULT 0.0,
    good_km REAL DEFAULT 0.0,
    fair_km REAL DEFAULT 0.0,
    poor_km REAL DEFAULT 0.0,
    average_pcu INTEGER DEFAULT 0
);
CREATE TABLE functional_classes (
    class_id TEXT PRIMARY KEY,
    class_code TEXT NOT NULL,
    class_name TEXT NOT NULL,
    scope_id TEXT NOT NULL,
    body_id TEXT NOT NULL,
    design_speed_min INTEGER,
    design_speed_max INTEGER,
    typical_width_m TEXT,
    description TEXT,
    FOREIGN KEY(scope_id) REFERENCES network_scopes(scope_id),
    FOREIGN KEY(body_id) REFERENCES governing_bodies(body_id)
);
CREATE TABLE governing_bodies (
    body_id TEXT PRIMARY KEY,
    body_name TEXT NOT NULL,
    acronym TEXT NOT NULL,
    scope_id TEXT NOT NULL,
    FOREIGN KEY(scope_id) REFERENCES network_scopes(scope_id)
);
CREATE TABLE network_scopes (
    scope_id TEXT PRIMARY KEY,
    scope_name TEXT NOT NULL,
    governing_ministry TEXT NOT NULL
);
CREATE TABLE pms_conditions (
    condition_id TEXT PRIMARY KEY,
    condition_name TEXT NOT NULL,
    severity_tier INTEGER NOT NULL
);
CREATE TABLE pms_decision_models (
    link_id TEXT PRIMARY KEY,
    current_iri REAL,
    current_rut_mm REAL,
    priority_score REAL,
    recommended_intervention TEXT,
    estimated_cost_ugx REAL,
    FOREIGN KEY(link_id) REFERENCES road_links(link_id)
);
CREATE TABLE road_links (
    link_id TEXT PRIMARY KEY,
    road_code TEXT,
    road_name TEXT NOT NULL,
    scope_id TEXT NOT NULL,
    body_id TEXT NOT NULL,
    class_id TEXT NOT NULL,
    surface_id TEXT NOT NULL,
    condition_id TEXT NOT NULL,
    length_km REAL NOT NULL,
    speed_kmh REAL DEFAULT 0.0,
    aadt INTEGER DEFAULT 0,
    pcu INTEGER DEFAULT 0,
    width_m REAL DEFAULT 6.0,
    lanes INTEGER DEFAULT 2,
    district_name TEXT NOT NULL,
    subcounty_name TEXT,
    parish_name TEXT,
    FOREIGN KEY(scope_id) REFERENCES network_scopes(scope_id),
    FOREIGN KEY(body_id) REFERENCES governing_bodies(body_id),
    FOREIGN KEY(class_id) REFERENCES functional_classes(class_id),
    FOREIGN KEY(surface_id) REFERENCES surface_types(surface_id),
    FOREIGN KEY(condition_id) REFERENCES pms_conditions(condition_id)
);
CREATE TABLE surface_types (
    surface_id TEXT PRIMARY KEY,
    surface_name TEXT NOT NULL,
    is_paved INTEGER NOT NULL
);
DELETE FROM "sqlite_sequence";
COMMIT;
